"""Explicit GENOS deployment paths generated by the operator handoff.

No config file means existing local/GENOS selection remains unchanged. Generation
assets stay lazy so ping is available before the mounted data becomes ready.
"""
import hashlib
import json
import os
from pathlib import Path

CONFIG = '00_SYSTEM/GENOS_SERVING_PATHS.json'
SCHEMA = 'genos-serving-paths-v1'


def install(root, *, environment=None):
    file = Path(root) / CONFIG
    if not file.exists():
        return None
    if file.is_symlink():
        raise ValueError('deployment path config must be a regular file')
    value = json.loads(file.read_text())
    if value.get('schema_version') != SCHEMA or value.get('selection') != 'operator-fixed':
        raise ValueError('unsupported deployment path config')
    for key in ('generation', 'runtime'):
        if not isinstance(value.get(key),str) or not Path(value[key]).is_absolute():
            raise ValueError('absolute deployment '+key+' required')
    if value.get('state') is not None:
        raise ValueError('this deployment binds existing runtime state without a separate state override')
    fingerprint = value.get('generation_manifest_sha256', '')
    if len(fingerprint) != 64 or any(c not in '0123456789abcdef' for c in fingerprint):
        raise ValueError('generation manifest fingerprint required')
    env = os.environ if environment is None else environment
    env['GENOS_GENERATION'] = value['generation']
    env['GENOS_RUNTIME_DIR'] = value['runtime']
    env.pop('GENOS_STATE_DIR', None)
    return value


def verify_generation(config, generation):
    if config is None:
        return
    if str(Path(generation)) != config['generation']:
        raise ValueError('generation differs from deployed operator binding')
    file = Path(generation)/'manifest.json'
    if file.is_symlink() or hashlib.sha256(file.read_bytes()).hexdigest() != config['generation_manifest_sha256']:
        raise ValueError('deployed generation manifest changed; explicit new deployment required')
